ts=[(pins['base_report'],br),(pins['base_monitor'],m),(pins['base_reconciliation'],reconpath),(pins['source_snapshot'],src),(pins['rule_observation'],obspath),(pins['current_selection'],curpath),(pins['category_snapshot'],catpath),(pins['derived_divider'],dp),(pins['derived_config'],cp),(pins['apply_code'],script),(pins['read_grid_helper'],helper),(pins['source_rule_code'],rulecode),(pins['prepare_code'],prepare),(sha(mp),mp)];[arg(x) for _,x in inputs];pinlines='\n'.join(f'{v}  {p}' for v,p in inputs);pydeps=str(R/'recovered-tmp/memory-headroom-20261103/pydeps')+':'+str(D);cmd=f'''#!/bin/bash\nset -euo pipefail\ncd {arg(R)}\nsha256sum -c <<'PINS'\n{pinlines}\nPINS\nexport PYTHONPATH={arg(pydeps)} OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1\npython3 process-watch-no-host-floor-20261105/watch_group.py --log-dir {arg('ural-source-v2-draft'+a.label+'-monitor-20261105')} --disk-path . --disk-floor-bytes 2147483648 --group-rss-kib 716800 --timeout 7200 -- python3 {arg(script)} --config {arg(cp)} --divider {arg(dp)} --candidate-rows {arg(base/'rows.u32le')} --candidate-runs {arg(base/'runs.u32le')} --physical-rows {arg(physical/'rows.u32le')} --physical-runs {arg(physical/'runs.u32le')} --output-prefix {arg(out/'candidate')}\n''';launch.write_text(cmd);print(json.dumps({'manifest':str(mp),'manifest_sha256':sha(mp),'launch':str(launch),'config_sha256':sha(cp),'divider_sha256':sha(dp)}))
